import{_ as t,o,c as a,a2 as n}from"./chunks/framework.BXzK3EA4.js";const u=JSON.parse('{"title":"29 - Ngrok Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"developers/design-documentation/29-ngrok-configuration.md","filePath":"developers/design-documentation/29-ngrok-configuration.md"}'),i={name:"developers/design-documentation/29-ngrok-configuration.md"};function r(s,e,d,l,c,h){return o(),a("div",null,[...e[0]||(e[0]=[n(`<h1 id="_29-ngrok-configuration" tabindex="-1">29 - Ngrok Configuration <a class="header-anchor" href="#_29-ngrok-configuration" aria-label="Permalink to &quot;29 - Ngrok Configuration&quot;">​</a></h1><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><p>The optional ngrok manager exposes the local Flask HTTP port for external webhook callbacks during self-hosted development or evaluation. It does not create a second Tradeboard API or bypass normal webhook/API authentication.</p><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">NGROK_ALLOW</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;TRUE&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">HOST_SERVER</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;https://your-domain.ngrok.app&#39;</span></span></code></pre></div><p><code>NGROK_ALLOW</code> is the actual enable flag. It defaults to <code>FALSE</code> in code (<code>os.getenv(&quot;NGROK_ALLOW&quot;, &quot;FALSE&quot;).upper() != &quot;TRUE&quot;</code>), so the comparison is case-insensitive and any value other than <code>TRUE</code> leaves the tunnel off. <code>.sample.env</code> ships <code>NGROK_ALLOW = &#39;FALSE&#39;</code> and <code>HOST_SERVER = &#39;http://127.0.0.1:5000&#39;</code>. There are no Tradeboard <code>NGROK_ENABLED</code>, <code>NGROK_AUTH_TOKEN</code>, or <code>NGROK_DOMAIN</code> environment variables in the current application contract. <code>pyngrok</code> obtains its ngrok credentials from its normal ngrok configuration.</p><p>When <code>HOST_SERVER</code> is a non-local URL, the manager extracts its host and asks ngrok for that custom domain. With a local <code>HOST_SERVER</code>, ngrok allocates a random public URL. A reserved custom domain must already be available to the configured ngrok account.</p><h2 id="startup-and-lifecycle" tabindex="-1">Startup And Lifecycle <a class="header-anchor" href="#startup-and-lifecycle" aria-label="Permalink to &quot;Startup And Lifecycle&quot;">​</a></h2><p>Direct app startup calls <code>start_ngrok_tunnel(FLASK_PORT)</code> only when <code>NGROK_ALLOW=TRUE</code>. In Flask debug/reloader mode it runs only in the serving child process.</p><p>The manager:</p><ol><li>Stops any existing pyngrok process before evaluating the flag.</li><li>Opens the tunnel to the configured Flask port.</li><li>Stores the returned public URL in process memory.</li><li>Registers <code>atexit</code>, SIGINT, and Unix SIGTERM cleanup.</li><li>Disconnects the tracked tunnel and kills the ngrok process during shutdown.</li></ol><p>Startup failure is logged and returns no tunnel URL; it does not replace application startup error handling.</p><h2 id="webhook-paths" tabindex="-1">Webhook Paths <a class="header-anchor" href="#webhook-paths" aria-label="Permalink to &quot;Webhook Paths&quot;">​</a></h2><p>Examples of routes that may need a public base URL include:</p><table tabindex="0"><thead><tr><th>Integration</th><th>Route shape</th></tr></thead><tbody><tr><td>Strategy RMS Engine</td><td><code>POST /strategy/webhook/&lt;token&gt;</code></td></tr><tr><td>Chartink</td><td><code>POST /chartink/webhook/&lt;webhook_id&gt;</code></td></tr><tr><td>Flow</td><td><code>POST /flow/webhook/&lt;token&gt;</code> or <code>/flow/webhook/&lt;token&gt;/&lt;symbol&gt;</code></td></tr><tr><td>TradingView / GoCharting</td><td>Their registered JSON automation routes</td></tr></tbody></table><p>The REST order API remains under <code>/api/v1</code>; <code>/api/v1/webhook/&lt;id&gt;</code> is not a registered generic webhook route.</p><h2 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to &quot;Security&quot;">​</a></h2><ul><li>A tunnel makes the selected Flask port internet-reachable. Keep Flask debug disabled for any non-loopback exposure.</li><li>Use webhook secrets/auth modes where the integration supports them.</li><li>Preserve rate limits, CSRF exemptions only on intended external callbacks, and API-key validation.</li><li>Do not log or commit ngrok credentials.</li><li>Prefer a stable HTTPS deployment URL for production integrations.</li></ul><h2 id="key-files" tabindex="-1">Key Files <a class="header-anchor" href="#key-files" aria-label="Permalink to &quot;Key Files&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Responsibility</th></tr></thead><tbody><tr><td><code>utils/ngrok_manager.py</code></td><td>Tunnel creation, URL access, signal cleanup</td></tr><tr><td><code>app.py</code></td><td>Direct-server startup gate</td></tr><tr><td><code>.sample.env</code></td><td><code>NGROK_ALLOW</code> and <code>HOST_SERVER</code> reference</td></tr></tbody></table>`,20)])])}const g=t(i,[["render",r]]);export{u as __pageData,g as default};
